argv:
$ErrorActionPreference='SilentlyContinue';$OutputEncoding=[Console]::OutputEncoding=[System.Text.UTF8Encoding]::new();
$out=[ordered]@{};
$out.time=(Get-Date).ToString('o');
$out.bridgeStatus=@();
foreach($u in @('http://127.0.0.1:17448/api/status','http://127.0.0.1:17448/api/operator-lifecycle','http://127.0.0.1:17448/api/projects/control-plane?inspect=0')){
 try{$r=Invoke-RestMethod -Uri $u -Method Get -TimeoutSec 4;$out.bridgeStatus += [ordered]@{url=$u;ok=$true;data=$r}}
 catch{$out.bridgeStatus += [ordered]@{url=$u;ok=$false;error=$_.Exception.Message}}
}
$out.processes=@(Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -match 'WebAIBridge|server\.js|start\.ps1|17448' } | Select-Object ProcessId,Name,CommandLine);
$out.checkouts=@();
$roots=@('E:\WebAIBridge','E:\web-ai-bridge','E:\bridge','C:\WebAIBridge','C:\web-ai-bridge','D:\WebAIBridge','D:\web-ai-bridge');
foreach($p in $roots){
 if(Test-Path "$p\.git"){
  $out.checkouts += [ordered]@{path=$p;branch=(git -C $p branch --show-current 2>$null);head=(git -C $p rev-parse HEAD 2>$null);status=(git -C $p status --porcelain 2>$null);remote=(git -C $p remote get-url origin 2>$null)}
 }
}
$out|ConvertTo-Json -Depth 12 -Compress
